async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder("utf-8");
  let state = initial;
  let physicalLine = 1;
  let recordIndex = 0;
  let eof = false;
  let returned = false;
  let parts = [];

  async function closeIterator() {
    if (returned) return;
    returned = true;

    const returnMethod = iterator.return;
    if (typeof returnMethod === "function") {
      await returnMethod.call(iterator);
    }
  }

  function takeLine() {
    let line = parts.length === 1 ? parts[0] : parts.join("");
    parts = [];

    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    return line;
  }

  async function processLine(line) {
    if (line.trim().length === 0) return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    state = result.state;
    recordIndex += 1;
    return result.done === true;
  }

  async function processText(text) {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) break;

      parts.push(text.slice(start, newline));
      const done = await processLine(takeLine());
      if (done) return true;

      physicalLine += 1;
      start = newline + 1;
    }

    if (start < text.length) {
      parts.push(text.slice(start));
    }

    return false;
  }

  try {
    while (true) {
      const step = await iterator.next();

      if (step.done) {
        eof = true;
        break;
      }

      const done = await processText(decoder.decode(step.value, { stream: true }));
      if (done) {
        await closeIterator();
        return state;
      }
    }

    if (await processText(decoder.decode())) {
      return state;
    }

    if (parts.length !== 0) {
      await processLine(takeLine());
    }

    return state;
  } catch (error) {
    if (!eof) {
      try {
        await closeIterator();
      } catch {
        // Preserve the original read/reduce error.
      }
    }

    throw error;
  }
}
